SELECT *, AVG(budget) OVER (PARTITION BY dept_name, location ORDER BY budget, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS budget_avg_2_prior, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) AS budget_share, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget DESC, id) AS event_seq, MIN(budget) OVER (PARTITION BY location) AS location_min_budget FROM departments;
